from __future__ import annotations

import json
from datetime import date
from pathlib import Path

from build_demo import EXAMS, PAGE, load_exam

BASE = Path(__file__).resolve().parent
DESTINATION = BASE / "demo" / "extended.html"


def build():
    data = {
        "generated": date.today().isoformat(),
        "exams": {exam: load_exam(exam) for exam in EXAMS},
    }
    payload = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
    payload = payload.replace("</", "<\\/").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    page = PAGE.replace("/*__DEMO_DATA__*/null", payload)
    page = page.replace("Root Atlas · 四考试词根图谱", "Root Atlas · 风格延伸版")
    page = page.replace("Vocabulary, connected", "Vocabulary, connected · Extended edition")
    page = page.replace("四考试词根图谱 · 离线研究演示", "四考试词根图谱 · 风格延伸版")
    page = page.replace('data-theme-choice="minimal" aria-pressed="false">简约</button>', 'data-theme-choice="minimal" aria-pressed="false">简约·极净</button>')
    page = page.replace('data-theme-choice="classical" aria-pressed="false">古典</button>', 'data-theme-choice="classical" aria-pressed="false">古典·典藏</button>')
    page = page.replace('data-theme-choice="elegant" aria-pressed="true">优雅</button>', 'data-theme-choice="elegant" aria-pressed="true">优雅·夜幕</button>')
    page = page.replace('data-theme-choice="joyful" aria-pressed="false">欢乐</button>', 'data-theme-choice="joyful" aria-pressed="false">欢乐·缤纷</button>')
    page = page.replace("rootAtlas.theme", "rootAtlas.extendedTheme")
    page = page.replace(
        '  let initialTheme="elegant";\n  try{const saved=localStorage.getItem("rootAtlas.extendedTheme");if(THEMES.includes(saved))initialTheme=saved;}catch{}',
        '  let initialTheme="elegant";\n  const requestedTheme=new URLSearchParams(location.search).get("theme");\n  if(THEMES.includes(requestedTheme))initialTheme=requestedTheme;\n  else{try{const saved=localStorage.getItem("rootAtlas.extendedTheme");if(THEMES.includes(saved))initialTheme=saved;}catch{}}',
    )
    page = page.replace("</style>", EXTENDED_CSS + "\n</style>")
    DESTINATION.write_text(page, encoding="utf-8")
    print(f"Built {DESTINATION} ({DESTINATION.stat().st_size / 1024 / 1024:.1f} MiB)")


